-- 04_zones_seoul25.sql
-- 서울 25개 구 경계 + 대표점. zones(id, name UNIQUE, boundary POLYGON NOT NULL SRID 0, marker_point POINT NOT NULL SRID 0)
-- 좌표는 WGS84 경도·위도를 SRID 0(평면)에 그대로 저장. WKT 순서는 POINT(경도 위도).
-- id 1~25는 행정구역 코드순(종로 11110 … 강동 11740). 프런트 GeoJSON의 zone_id와 같은 값을 쓸 것.
--
-- 가공: 행정동 경계(427개)를 구 단위로 합침 → 10m 토폴로지 보존 단순화(구끼리 공유 경계를 함께 단순화해 겹침·빈틈 0)
--       → 소수 6자리 → 모든 구 is_valid, 단일 Polygon(MultiPolygon·구멍 없음, 한강 수면 포함 경계)
--       marker_point = 단순화된 경계의 representative_point(구 안에 반드시 포함)
-- 출처 표기(CC BY 4.0 / 공공누리 1유형, 삭제 금지):
--   "본 데이터는 통계청 통계지리정보서비스(SGIS, https://sgis.kostat.go.kr)에서 공공누리 제1유형으로 개방한
--    행정동 경계를 가공한 것이며(가공: vuski/admdongkor, https://github.com/vuski/admdongkor), CC BY 4.0으로 배포됩니다."
--   (이 파일은 위 자료를 다시 합치고 단순화한 파생물임)
--
-- [주의] 이 스크립트는 임시 구역 6개(종로·중·용산·성동·광진·마포)를 지우고 25개로 다시 넣습니다.
--   zones를 참조하는 FK(제보·구역 집계·forecast_spots.zone_id 등)가 있으면 DELETE가 막히거나, 막지 않으면 고아 행이 생깁니다.
--   테스트 데이터뿐이라면 참조 행을 먼저 지우거나 아래 ALTERNATIVE(이름 기준 갱신)를 쓰세요.

SET NAMES utf8mb4;
START TRANSACTION;

-- 1) 임시 구역 삭제 (이름이 겹치는 6개 + id 1~25와 충돌할 수 있는 행)
DELETE FROM zones
 WHERE name IN ('종로구', '중구', '용산구', '성동구', '광진구', '마포구')
    OR id BETWEEN 1 AND 25;

